"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["29805"],{50090(e){e.exports=JSON.parse('{"id":"V4-218","slug":"generative-ai-in-finance","term":"Generative AI in Finance","also_known_as":[],"difficulty":"Intermediate","definition":"Generative AI in finance is the use of artificial intelligence systems that can create new content, such as text, code, summaries and analysis, to support financial services tasks, from customer service to research, compliance and software development.","explanation":["Generative AI uses large language models and similar technologies, trained on vast amounts of data, to produce human-like text and other outputs in response to prompts. Its use in finance grew rapidly after such tools became widely available in late 2022.","Common applications include customer service chatbots and virtual assistants; summarising research reports, earnings calls and regulatory documents; drafting reports, emails and client communications; helping analysts and advisers find information quickly; assisting with coding and software development; and supporting compliance, such as reviewing documents and monitoring communications.","For example, a bank might give its financial advisers an AI assistant that searches internal research and drafts summaries for client meetings, while the adviser checks and approves the final content.","Generative AI also brings risks. Models can produce confident but incorrect information, sometimes called hallucinations; they may reflect biases in their training data; and they raise concerns about data privacy, security, intellectual property and accountability.","Regulators expect firms to manage these risks under existing rules, and new rules, such as the EU AI Act, set additional requirements. Firms typically keep humans involved in important decisions."],"note":"","total":1725,"prev":{"slug":"generally-accepted-accounting-principles","term":"Generally Accepted Accounting Principles (GAAP)"},"next":{"slug":"geometric-mean","term":"Geometric Mean"}}')}}]);